    /** The last sheet's today a reminder was written for the claim; null for a claim never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** Whether a reminder ever escalated the claim; a claim is escalated once at most. */
    @Column(nullable = false)
    private boolean escalated;

    /** Whether a steward waived the claim's late charge; a waived claim bears no late charge from then on. */
    @Column(nullable = false)
    private boolean waived;

    /** The sheet's today when the claim last went to REVIEW; null for a claim never in review. */
    @Column(name = "review_on")
    private LocalDate reviewOn;

    /** A copy of the claim as it stood at the end of an earlier date: the status it had then, its due fixed then
     *  (null: not settled then) and its binding then. Only worked out, never saved. */
    public Claim asOf(ClaimStatus status, BigDecimal due, boolean stated, BigDecimal statedDue) {
        Claim then = new Claim(sheetId, personId, amount, date, note, corrects);
        then.id = id;
        then.status = status.name();
        then.number = number;
        then.due = due;
        then.openedBy = openedBy;
        then.editedBy = editedBy;
        then.settleBatch = settleBatch;
        then.dueBy = dueBy;
        then.dueFrom = dueFrom;
        then.dueTerms = dueTerms;
        then.correctsDate = correctsDate;
        then.listed = listed;
        then.deferredUntil = deferredUntil;
        then.remindedOn = remindedOn;
        then.escalated = escalated;
        then.waived = waived;
        then.reviewOn = reviewOn;
        then.proofs = proofs;
        then.proofsPhoto = proofsPhoto;
        then.splitFrom = splitFrom;
        then.lateEntry = lateEntry;
        then.ref = ref;
        then.tags = tags;
        then.tagsUsed = tagsUsed;
        then.voidReason = status == ClaimStatus.VOID ? voidReason : null;
        then.bind(stated, statedDue);
        return then;
    }

    /** A copy of the claim for a person on another sheet, as a transfer carries it: its status, dates, note, frozen
     *  due, opener and editor, deferral, proofs and tags; unbound (a statement's figure is lost), with no number (the
     *  other sheet gives it one), no reference, batch, lock or split. Not saved. */
    public Claim transferTo(String toSheetId, Long toPersonId) {
        Claim moved = new Claim(toSheetId, toPersonId, amount, date, note, null);
        moved.status = status;
        moved.due = due;
        moved.openedBy = openedBy;
        moved.editedBy = editedBy;
        moved.dueBy = dueBy;
        moved.dueFrom = dueFrom;
        moved.dueTerms = dueTerms;
        moved.correctsDate = correctsDate;
        moved.deferredUntil = deferredUntil;
        moved.remindedOn = remindedOn;
        moved.escalated = escalated;
        moved.waived = waived;
        moved.reviewOn = reviewOn;
        moved.proofs = proofs;
        moved.proofsPhoto = proofsPhoto;
        moved.lateEntry = lateEntry;
        moved.tags = tags;
        moved.tagsUsed = tagsUsed;
        moved.voidReason = voidReason;
        return moved;
    }

    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
package net.officefloor.hq.app.claim;

import java.util.List;

/** A claim as the screen shows it: its amount with two decimals, its date (YYYY-MM-DD) its note, its status, its number (null when it has none)
 * and its due fixed when it was settled (null when it has none), and who opened it (null when never opened);
 * whether its person's last statement binds it, and the figure it binds it to (null: none, or n/a); the number of the
 * claim it corrects (null when it is not a correction); and the date its rounding goes by (YYYY-MM-DD: a correction's is
 * the date of the claim it corrects, else its own); and its due-by (YYYY-MM-DD), fixed when it was created; and its status log, oldest first
 * (<STATUS> by <user> on <date> due=<due>); and the date it is deferred until (YYYY-MM-DD; null when never deferred); and its proofs count, and how many of them are receipts and how many photos; and the number of the claim it was split off from (null when not made by a split); and whether it was added while its period was soft-closed; and the last day it was reminded (YYYY-MM-DD; null when never reminded); and its external reference (null when none); and its tags, sorted (empty when none), and every tag it has ever carried, sorted; and the reason it was voided with (null when none); and its comments, oldest first (<user> on <date>: <text>); and who last edited it (null when never edited); and the number of the bulk settle batch that settled it (null when none); and its lines, in the order added (<label> <qty> x <unit>); and the sheet's today when it last went to REVIEW (YYYY-MM-DD; null when never); and whether its late charge was waived. */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String due, String openedBy,
        boolean stated, String statedDue, String corrects, String roundsOn, String dueBy,
        List<String> log, String deferredUntil, int proofs, int proofsReceipt, int proofsPhoto, String splitFrom, boolean lateEntry, String remindedOn, String ref,
        List<String> tags, List<String> tagsUsed, String voidReason, List<String> comments, String editedBy,
        Integer settleBatch, List<String> lines, String reviewOn, boolean waived) {

    public static ClaimResponse from(Claim claim, List<String> log, List<String> comments, List<String> lines) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() == null ? null : claim.getDue().setScale(2).toPlainString(), claim.getOpenedBy(),
                claim.isStated(), claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString(),
                claim.getCorrects(), claim.getRoundsOn().toString(), claim.getDueBy().toString(), log,
                claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(), claim.getProofs(),
                claim.getProofsReceipt(), claim.getProofsPhoto(),
                claim.getSplitFrom(), claim.isLateEntry(),
                claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef(),
                Tags.list(claim.getTags()), Tags.list(claim.getTagsUsed()), claim.getVoidReason(), comments, claim.getEditedBy(),
                claim.getSettleBatch(), lines, claim.getReviewOn() == null ? null : claim.getReviewOn().toString(),
                claim.isWaived());
    }
}

