package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.statement.Statement;

/** A person as the screen shows them: their grade in force on the sheet's today, and every grade they were given
 *  with its from-date (null for the first, which applies from the beginning of time), with their statement count
 *  and their last statement's due-total and date (null with none), and the date they are retired from (null: not
 *  retired), and whether they have any hold, and their holds (earliest first), and the ids of their patrons in the order they were named, and their own terms in days in force on the sheet's today (null: none), and their contact (null: none), and their aliases, sorted ignoring case, and whether
 *  they clash: their name or an alias is in use on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null: none), and their past retirements (earliest first), and their tags, sorted, and their snapshots, oldest first, and their statements, by
 *  the date each was taken as of (in the order they stand on the same date), and their flag's reason while it is in
 *  force on the sheet's today (null: none in force). */
public record PersonResponse(long id, String name, String grade, List<DatedGrade> grades, long version,
        int statementCount, String statedTotal, String statementDate, String retiredFrom, boolean held,
        List<Hold> holds, List<Long> patronIds, Integer terms,
        String contact, List<String> aliases, boolean clashing, String origin,
        List<Retirement> retirements, List<String> tags, List<Snapshot> snapshots,
        List<StatementLine> statements, String flag) {

    /** A statement still standing: the date it was taken as of and the due-total it recorded. */
    public record StatementLine(String date, String dueTotal) {
    }

    /** A past retirement, from a date to the day they were unretired. */
    public record Retirement(String from, String to) {
    }

// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of view: while the screen's `asof` search param holds a date, every read of a sheet asks for the
// sheet as it stood at the end of that date, and every change is refused here, before it reaches the store
// (so each form and action shows its usual error). Loading a sheet (PUT /api/sheets/<id>) is not a change.
export const ASOF_PARAM = 'asof';

/** The date the screen shows the sheet as of (YYYY-MM-DD), or '' while it shows the sheet as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
  try {
    const parsed: unknown = JSON.parse(raw);
    return typeof parsed === 'string' ? parsed : raw;
  } catch {
    return raw;
  }
}

const isSheetLoad = (path: string) => /^\/api\/sheets\/[^/?]+$/.test(path);

async function send<T>(path: string, init?: RequestInit, live = false): Promise<T> {
  const asOf = live ? '' : currentAsOf();
  if (asOf && init?.method && init.method !== 'GET' && !isSheetLoad(path)) {
    throw new HttpError(`${init.method} ${path} -> refused while the sheet is shown as of ${asOf}`, 400);
  }
  if (asOf && !init?.method && path.startsWith('/api/sheets/')) {
    path += `${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);

